import asyncio
import signal
import json
import unicodedata
from aiohttp import web
from urllib.parse import urlparse
import hashlib
import hmac
import os
import re

SECRET_KEY = os.urandom(32)
ALLOWED_REDIRECT_DOMAINS = ['accounts.google.com', 'login.microsoft.com', 'auth.company.com']

class GracefulShutdown:
    def __init__(self):
        self.shutdown_event = asyncio.Event()
        self.active_connections = 0

    def begin_request(self):
        self.active_connections += 1

    def end_request(self):
        self.active_connections -= 1
        if self.shutdown_event.is_set() and self.active_connections == 0:
            raise web.GracefulExit()

    def initiate_shutdown(self):
        self.shutdown_event.set()

shutdown_handler = GracefulShutdown()

def normalize_domain(domain: str) -> str:
    """Normalize a domain name for comparison.
    Uses NFKC normalization as recommended for domain names."""
    normalized = unicodedata.normalize('NFKC', domain)
    return normalized.lower().strip()

def is_homograph_safe(domain: str) -> bool:
    """Check if domain contains mixed scripts that could indicate homograph attack."""
    scripts_seen = set()
    for char in domain:
        if char in '.:-':
            continue
        script = unicodedata.category(char)
        if script.startswith('L'):
            try:
                script_name = unicodedata.script(char) if hasattr(unicodedata, 'script') else 'COMMON'
            except (ValueError, AttributeError):
                script_name = unicodedata.name(char, '').split(' ')[0]
            scripts_seen.add(script_name)
    return len(scripts_seen) <= 1

def contains_non_ascii(domain: str) -> bool:
    """Reject any domain with non-ASCII characters entirely."""
    try:
        domain.encode('ascii')
        return False
    except UnicodeEncodeError:
        return True

def validate_redirect_url(url: str) -> bool:
    """Validate that a redirect URL points to an allowed domain."""
    try:
        parsed = urlparse(url)
        if not parsed.scheme in ('https',):
            return False
        domain = parsed.hostname
        if domain is None:
            return False
        if contains_non_ascii(domain):
            return False
        normalized = normalize_domain(domain)
        if not is_homograph_safe(normalized):
            return False
        for allowed in ALLOWED_REDIRECT_DOMAINS:
            if domain_matches(normalized, allowed):
                return True
        return False
    except Exception:
        return False

def domain_matches(candidate: str, allowed: str) -> bool:
    """Check if candidate domain matches an allowed domain.
    Supports exact match and subdomain matching."""
    if candidate == allowed:
        return True
    if candidate.endswith('.' + allowed):
        return True
    return False

def generate_session_token(user_id: str) -> str:
    """Generate HMAC-based session token."""
    payload = f"{user_id}:{os.urandom(16).hex()}"
    signature = hmac.new(SECRET_KEY, payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}:{signature}"

@web.middleware
async def tracking_middleware(request, handler):
    shutdown_handler.begin_request()
    try:
        response = await handler(request)
        return response
    finally:
        shutdown_handler.end_request()

async def handle_login(request: web.Request) -> web.Response:
    """Handle OAuth login redirect."""
    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({'error': 'Invalid JSON'}, status=400)

    redirect_url = data.get('redirect_uri', '')
    if not redirect_url:
        return web.json_response({'error': 'Missing redirect_uri'}, status=400)

    if not validate_redirect_url(redirect_url):
        return web.json_response({'error': 'Invalid redirect domain'}, status=403)

    return web.json_response({
        'status': 'authenticated',
        'redirect_to': redirect_url
    })

async def handle_health(request: web.Request) -> web.Response:
    if shutdown_handler.shutdown_event.is_set():
        return web.json_response({'status': 'shutting_down'}, status=503)
    return web.json_response({'status': 'healthy'})

async def handle_callback(request: web.Request) -> web.Response:
    """Handle OAuth callback with state validation."""
    state = request.query.get('state', '')
    code = request.query.get('code', '')
    if not state or not code:
        return web.json_response({'error': 'Missing parameters'}, status=400)
    return web.json_response({'status': 'callback_received', 'code': code})

def create_app() -> web.Application:
    app = web.Application(middlewares=[tracking_middleware])
    app.router.add_post('/api/login', handle_login)
    app.router.add_get('/api/health', handle_health)
    app.router.add_get('/api/callback', handle_callback)
    return app

def setup_signal_handlers(loop):
    for sig in (signal.SIGTERM, signal.SIGINT):
        loop.add_signal_handler(sig, shutdown_handler.initiate_shutdown)

if __name__ == '__main__':
    app = create_app()
    web.run_app(app, host='0.0.0.0', port=8080)
